export const aiTemelGiris: { q: string; a: string }[] = [
  { q: 'Yapay zeka tam olarak nedir?', a: 'Bilgisayarın, normalde insan aklı gerektiren işleri yapabilmesidir: bir fotoğrafta kedi olduğunu anlamak, bir cümleyi çevirmek, bir soruya cevap yazmak, satranç oynamak. Sihir değildir; sonuçta matematik ve çok fazla hesaplamadır. "Zeka" kelimesi benzetmedir: bilgisayar düşünmez, örüntüleri (tekrar eden kalıpları) çok iyi yakalar.' },
  { q: 'Bilgisayar programıyla yapay zeka arasındaki fark ne?', a: 'Normal programda kuralları insan yazar: "Eğer sıcaklık 30\'dan büyükse klimayı aç." Yapay zekada kuralı insan yazmaz; bilgisayara binlerce örnek gösterilir ve kuralı kendisi çıkarır. Örneğin 10.000 spam ve 10.000 normal e-posta gösterirsin, hangi kelimelerin spam işareti olduğunu kendisi bulur. Buna "makine öğrenmesi" denir.' },
  { q: 'Makine öğrenmesi, derin öğrenme, yapay zeka: hangisi ne?', a: 'İç içe üç daire gibi düşün. En dışta yapay zeka (akıllı görünen her sistem). Onun içinde makine öğrenmesi (veriden öğrenen sistemler). Onun da içinde derin öğrenme (insan beynindeki sinir hücrelerinden esinlenen, çok katmanlı "yapay sinir ağları"). ChatGPT, yüz tanıma, sesli asistanlar derin öğrenmedir.' },
  { q: 'Model ne demek?', a: 'Eğitim sonunda ortaya çıkan, soruyu alıp cevap üreten şeye "model" denir. Bir tarif defteri gibi düşün: eğitim sırasında deneye deneye en iyi tarifi (milyonlarca sayıyı) bulur; sonra bu tarifle yeni gelen her soruya cevap üretir. "GPT-5 modeli", "Llama modeli" dendiğinde kastedilen budur.' },
  { q: 'Eğitim ne demek, nasıl oluyor?', a: 'Modele örnek verip tahmin yaptırmak, yanlışını ölçmek ve içindeki sayıları biraz düzeltmek; bunu milyonlarca kez tekrarlamak. Bisiklet öğrenmeye benzer: her düşüşte dengeyi biraz daha iyi ayarlarsın. Büyük modellerin eğitimi aylar sürer ve milyonlarca dolara mal olur; ama eğitilmiş modeli kullanmak (soru sormak) saniyeler alır ve ucuzdur.' },
  { q: 'ChatGPT gibi sohbet botları nasıl çalışıyor?', a: 'Bunlara "büyük dil modeli" (LLM) denir. İnternetin büyük bölümünü okumuş ve tek bir şeyi öğrenmiştir: bir metnin devamında hangi kelimenin gelme ihtimalinin yüksek olduğunu tahmin etmek. "Türkiye\'nin başkenti" yazınca "Ankara" der, çünkü milyonlarca metinde bu ikili yan yana geçmiştir. Cümle cümle değil, kelime parçası parçası (token) üretir; her parça için bir sonrakini tahmin eder. Bu kadar basit bir mekanizma, yeterince büyük ölçekte şaşırtıcı derecede akıllı görünür.' },
  { q: 'Neden bazen yanlış ama kendinden emin cevap veriyor?', a: 'Çünkü "doğru" değil "olası" kelimeyi üretir. Gerçekleri bilen bir ansiklopedi değil, akıcı metin üreten bir makinedir. Olmayan bir kitabı, var olmayan bir yasa maddesini akıcı biçimde uydurabilir. Buna "halüsinasyon" denir. Çözümü: ona kaynak vermek, doğrulatmak ve önemli işlerde insan kontrolü.' },
  { q: 'Üretken yapay zeka ne demek?', a: 'Yeni içerik üreten modeller: metin (ChatGPT, Claude), görsel (Midjourney, Stable Diffusion), ses, müzik, video. Eski yapay zeka sınıflandırırdı ("bu spam mı?"); üretken yapay zeka yaratır ("bana bir reklam metni yaz"). 2022\'den beri yaşanan patlama budur.' },
  { q: 'Yapay zeka neden şimdi bu kadar gündemde?', a: 'Üç şey aynı anda olgunlaştı: internet sayesinde devasa veri, oyun kartlarından (GPU) gelen ucuz ve güçlü hesaplama gücü, 2017\'de bulunan "Transformer" adlı yeni mimari. 2022\'de ChatGPT bunu herkesin kullanabildiği bir sohbet kutusuna koydu; o günden beri her ay yeni bir model çıkıyor.' },
  { q: 'Öğrenmek için matematik ve programlama şart mı?', a: 'Kullanmak için hiçbiri şart değil; iyi soru sormayı öğrenmek yeter (Prompt Mühendisliği başlığı). Uygulama geliştirmek için biraz programlama (Python veya JavaScript) gerekir. Kendi modelini eğitmek için lise matematiği fikri (ortalama, olasılık, eğim) yeterlidir; hesabı kütüphaneler yapar. Bu bölüm matematiksiz anlatır.' },
  { q: 'Hangi dil, hangi araçlar?', a: 'Yapay zeka dünyasının dili Python\'dır: scikit-learn (klasik öğrenme), PyTorch (derin öğrenme), Transformers (hazır modeller). Modelleri uygulamadan çağırmak için JavaScript de yaygın. Başlangıç için tarayıcıdan ChatGPT/Claude ve ücretsiz Google Colab (bulutta Python) yeter; bilgisayarına bir şey kurman gerekmez.' },
  { q: 'Yapay zeka işimi elimden alır mı?', a: 'Belirli görevleri (özet çıkarma, taslak yazma, veri girişi, basit kod) hızlandırır ve kısmen otomatikleştirir; meslekleri değil görevleri değiştirir. Onu iyi kullanan kişi, kullanmayana göre çok daha üretken olur. Bu yüzden "nasıl çalıştığını anlamak ve doğru kullanmak" bugün herkes için temel beceri.' },
  { q: 'Bu bölümde ne öğreneceğim?', a: 'Kavramları ve sözlüğü: model, eğitim, veri, öğrenme türleri, başarı nasıl ölçülür, sinir ağı nedir, ChatGPT\'nin altındaki Transformer nasıl çalışır, görsel üreten modeller nasıl çalışır, nerelerde kullanılır, etik sınırlar neler. Hiçbir kod yazman gerekmez; örnek kodlar sadece "böyle görünüyor" demek için.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki konu sırası öğrenme sırasıdır: Temel Kavramlar → Öğrenme Türleri → Veri → Model ve Eğitim → Değerlendirme → Klasik Algoritmalar → Sinir Ağları → Transformer ve LLM → Üretken Modeller → Uygulama Alanları → Araçlar → Etik → Yol Haritası. Her satıra tıklayınca sağda "Basitçe" kutusu günlük hayattan benzetmeyle anlatır; en altta küçük bir soru var.' },
]

